+$call = @{ WorkspacePath=$workspacePath; PluginRoot=$pluginRoot; CacheRoot=$cachePath; TimeoutSeconds=180 }
+$resultLines = @()
+switch ($Action) {
+    'Start' {
+        Write-Output 'PLUGIN_IDENTITY'
+        Get-Content -LiteralPath (Join-Path $pluginRoot '.codex-plugin/plugin.json') -Raw
+        $resultLines += & $wrapperPath @call -Command Status
+        $requestId = 'req-' + (Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssZ') + '-unitgreen-r11'
+        $turnParameters = [ordered]@{
+            requestId=$requestId
+            queryTitle='Hostile validation round 11 of IMPL-UNITGREEN-001'
+            queryText='Independent read-only unitgreen-r11 review. Full authorized request: docs/receipts/hv/20261103T113108-unitgreen-r11.request.jsonl. No builds, restores or tests. Review code, supplied TRX, receipts, plan and live stores. Model proof: gpt-6-astra effort max in own rollout turn_context at 2026-11-03T17:31:13.567Z; Codex thread 01a1a277-00cd-7ca3-919d-b61486d98f9e. Read add-profile SKILL.md and one profile file in full, then full root marker with credentials suppressed. Do not mutate TODOs, requirements, triage or memories. Operational failures do not determine product acceptance.'
