+            interpretation='Class 1 independent hostile validation against all 40 claims, supplied evidence only, scanner overridden and hostile-environment runs out of scope.'
+            tags=@('unitgreen-r11','IMPL-UNITGREEN-001','gpt-6-astra','effort-max')
+        }
+        $resultLines += & $wrapperPath @call -Command Invoke -Method 'workflow.sessionlog.beginTurn' -ParamsObject $turnParameters
+        $resultLines += & $wrapperPath @call -Command Status
+    }
+    'Memories' {
+        $rawLines = & $wrapperPath @call -Command Invoke -Method 'workflow.memory.list' -ParamsObject ([ordered]@{scope=$Scope})
+        foreach ($rawLine in $rawLines) {
+            try {
+                $memoryEnvelope = $rawLine | ConvertFrom-Json -AsHashtable -Depth 100
+                function Remove-ExcludedMemory {
+                    param($Value)
+                    if ($Value -is [System.Collections.IDictionary]) {
+                        if ($Value['id'] -eq 'MEMORY-PROCESS-007') { return $null }
+                        $cleanMap = [ordered]@{}
+                        foreach ($field in $Value.Keys) { $cleanMap[$field] = Remove-ExcludedMemory $Value[$field] }
+                        return $cleanMap
+                    }
+                    if ($Value -is [array]) { return ,@($Value | ForEach-Object { Remove-ExcludedMemory $_ } | Where-Object { $null -ne $_ }) }
+                    return $Value
+                }
+                $resultLines += (Remove-ExcludedMemory $memoryEnvelope | ConvertTo-Json -Depth 100)
+            } catch { throw 'Memory response could not be safely filtered; excluded memory was not rendered.' }
+        }
+    }
+    'History' {
+        $query = [ordered]@{agent='Codex'; limit=10; offset=0}
+        if ($SessionId) { $query['sessionId']=$SessionId }
+        $resultLines += & $wrapperPath @call -Command Invoke -Method 'workflow.sessionlog.queryHistory' -ParamsObject $query
+    }
+    'Log' {
+        $resultLines += & $wrapperPath @call -Command Invoke -Method 'workflow.sessionlog.appendDialog' -ParamsObject ([ordered]@{dialogItems=@([ordered]@{timestamp=(Get-Date).ToUniversalTime().ToString('o');role='model';category='observation';content=$Text})})
+    }
+    'Read' {
+        if ($Method -notmatch '^workflow\.(requirements|todo|memory)\.(get|effective|list|listMappings|getFunctional|getTechnical|getTesting|getMapping|listFunctional|listTechnical|listTesting|getTechnicalRequirementsForFunctional|getTestingRequirementsForTechnical)$') { throw 'Read method is not allowlisted.' }
+        $query = [ordered]@{}
+        if ($Id) { $query['id']=$Id }
+        if ($Scope) { $query['scope']=$Scope }
+        $resultLines += & $wrapperPath @call -Command Invoke -Method $Method -ParamsObject $query
+    }
+}
+$resultText = $resultLines -join "`n"
+$resultText = $resultText -replace '(?i)(apiKey[\s"'':=]+)[A-Za-z0-9_+/=-]{20,}', '$1[REDACTED:api-key]'
+$receipt = [ordered]@{timestampUtc=(Get-Date).ToUniversalTime().ToString('o');timestampLocal=(Get-Date).ToString('s');action=$Action;method=$Method;id=$Id;scope=$Scope;cacheRoot=$cachePath;output=$resultText}
+$receipt | ConvertTo-Json -Depth 100 | Set-Content -LiteralPath (Join-Path $receiptDirectory ('hv-ug-r11-' + $OutputName + '.json')) -Encoding utf8
+Write-Output $resultText
+Write-Output ('TIMESTAMP_LOCAL ' + (Get-Date).ToString('s'))
*** End Patch"));
